const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12c6 4 12 4 18 0 M11 13h2',file:'M6 2h8l4 4v16H6z M13 2v5h5 M9 12h6 M9 16h6',bookmark:'M6 3h12v19l-6-4-6 4z',school:'m2 9 10-6 10 6-10 6z M6 12v6l6 3 6-3v-6 M22 9v8',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',check:'m5 12 4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',pin:'M19 9c0 5-7 13-7 13S5 14 5 9a7 7 0 1 1 14 0 M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0',arrow:'M4 12h16 m-6-6 6 6-6 6',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10 M10 22h4',building:'M4 22V3h12v19 M16 10h5v12 M1 22h22 M8 7h4 M8 11h4 M8 15h4 M9 22v-3h3v3',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',menu:'M3 6h18 M3 12h18 M3 18h18',plus:'M12 4v16 M4 12h16',chart:'M3 3v18h19 M7 16v-5 M12 16V7 M17 16V4',logout:'M10 4H4v16h6 M10 12h12 m-4-4 4 4-4 4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.briefcase}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={students:[{id:1,name:'Faril Putra Pratama',kelas:'XI RPL 6',major:'RPL',email:'faril@example.com',status:'verified'},{id:2,name:'Nadia Putri',kelas:'XI DKV 1',major:'DKV',email:'nadia@example.com',status:'pending'},{id:3,name:'Rizky Ramadhan',kelas:'XI TKJ 2',major:'TKJ',email:'rizky@example.com',status:'pending'}],companies:[{id:1,name:'Nusa Digital',city:'Bekasi',sector:'Teknologi informasi',contact:'hubin@nusa.example'},{id:2,name:'Kreasi Studio',city:'Jakarta',sector:'Desain & kreatif',contact:'karier@kreasi.example'},{id:3,name:'Aruna Teknologi',city:'Bekasi',sector:'Teknologi informasi',contact:'hr@aruna.example'},{id:4,name:'Lintas Network',city:'Jakarta',sector:'Jaringan komputer',contact:'hr@lintas.example'},{id:5,name:'Aksara Media',city:'Bandung',sector:'Media digital',contact:'hr@aksara.example'},{id:6,name:'Sentra Niaga',city:'Bekasi',sector:'Perdagangan',contact:'hr@sentra.example'}],jobs:[{id:1,company:1,title:'Front-End Developer Intern',major:'RPL',mode:'Hybrid',quota:4,duration:'6 bulan',description:'Bangun pengalaman nyata mengembangkan antarmuka aplikasi web bersama tim produk. Kamu akan didampingi mentor, mengikuti diskusi desain, dan mengerjakan fitur yang digunakan pengguna.',skills:'HTML & CSS, JavaScript, Dasar Git'},{id:2,company:2,title:'UI/UX Designer Intern',major:'DKV',mode:'On-site',quota:2,duration:'6 bulan',description:'Belajar merancang pengalaman digital, menyusun wireframe, dan membuat prototipe interaktif bersama tim desain.',skills:'Figma, Design thinking, Komunikasi'},{id:3,company:3,title:'Back-End Developer Intern',major:'RPL',mode:'Hybrid',quota:3,duration:'6 bulan',description:'Pelajari pengembangan API, pengolahan data, dan pengujian aplikasi melalui proyek yang didampingi mentor.',skills:'Python / PHP, SQL, Dasar API'},{id:4,company:4,title:'IT Support Intern',major:'TKJ',mode:'On-site',quota:5,duration:'3 bulan',description:'Dampingi tim IT dalam pemeliharaan perangkat, penanganan kendala pengguna, dan konfigurasi jaringan kantor.',skills:'Jaringan dasar, Troubleshooting, Kerja tim'},{id:5,company:5,title:'Content Designer Intern',major:'DKV',mode:'Remote',quota:2,duration:'3 bulan',description:'Kembangkan konten visual dan sistem desain media sosial bersama tim kreatif.',skills:'Illustrator, Tipografi, Desain visual'},{id:6,company:6,title:'Administrasi Keuangan Intern',major:'AKL',mode:'On-site',quota:3,duration:'6 bulan',description:'Pelajari administrasi transaksi, pencatatan dokumen, dan laporan keuangan dasar bersama pembimbing.',skills:'Spreadsheet, Ketelitian, Akuntansi dasar'}],apps:[{id:1,student:1,job:1,status:'pending',date:'9 Sep 2026',note:'Saya ingin memperdalam kemampuan pengembangan web.'},{id:2,student:1,job:3,status:'approved',date:'7 Sep 2026',note:'Tertarik pada pengembangan API.'},{id:3,student:1,job:4,status:'rejected',date:'4 Sep 2026',note:'',reason:'Posisi lebih sesuai untuk kompetensi jaringan TKJ.'}],history:[{id:100,studentName:'Aditya Pratama',kelas:'XII RPL 2',company:1,title:'Web Developer Intern',period:'Jan – Jun 2026',note:'Menyelesaikan pengembangan dashboard internal.'},{id:101,studentName:'Salsa Maharani',kelas:'XII DKV 1',company:2,title:'Graphic Designer Intern',period:'Jan – Jun 2026',note:'Menyelesaikan portofolio desain kampanye.'}],saved:[],current:1};
let db;let storageFailed=false;try{db=JSON.parse(localStorage.getItem('findmypkl-v1'))||structuredClone(seed)}catch{db=structuredClone(seed);storageFailed=true}let role='siswa',page=1,query='',major='Semua',city='Semua',mode='Semua',sort='new',statusFilter='Semua';const app=document.querySelector('#app'),modal=document.querySelector('#modal');const student=()=>db.students.find(s=>s.id===db.current)||db.students[0];const co=id=>db.companies.find(c=>c.id===id)||{name:'Mitra tidak tersedia',city:'—'};const job=id=>db.jobs.find(j=>j.id===id);const mine=()=>db.apps.filter(a=>a.student===student().id);const uid=()=>Date.now()+Math.floor(Math.random()*1000);const labels={pending:'Menunggu HUBIN',approved:'Seleksi perusahaan',accepted:'Diterima perusahaan',rejected:'Ditolak HUBIN',notaccepted:'Tidak lolos seleksi',active:'PKL berlangsung',completed:'PKL selesai'};
function badge(s){return `<span class="badge ${['accepted','active','completed','verified'].includes(s)?'good':['rejected','notaccepted'].includes(s)?'bad':s==='approved'?'blue':''}">${labels[s]||({verified:'Terverifikasi',pending:'Menunggu verifikasi'}[s])||esc(s)}</span>`}
function persist(){try{localStorage.setItem('findmypkl-v1',JSON.stringify(db))}catch{toast('Penyimpanan browser tidak tersedia. Perubahan hanya tersimpan selama sesi ini.')}}function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',4000)}function nav(url){location.hash=url}function route(){return location.hash.slice(1)||'publik'}function logo(j){return `<div class="company-logo logo-${j.company%5}">${esc(co(j.company).name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div>`}
const studentNav=[['beranda','home','Beranda'],['cari','search','Cari PKL'],['pengajuan','file','Pengajuan saya'],['tersimpan','bookmark','PKL tersimpan'],['aktif','briefcase','PKL saya']];const hubinNav=[['dashboard','chart','Dashboard'],['verifikasi','users','Verifikasi siswa'],['review','file','Pengajuan siswa'],['monitoring','chart','Monitoring PKL'],['lowongan','briefcase','Kelola lowongan'],['mitra','building','Mitra perusahaan'],['riwayat','clock','Riwayat PKL']];
function render(){let r=route();if(r==='publik'){app.innerHTML=publicHome();return}const menu=role==='siswa'?studentNav:hubinNav;const title=menu.find(x=>x[0]===r)?.[2]||(r.startsWith('detail')?'Detail lowongan':r==='daftar'?'Pendaftaran siswa':'Find My PKL');app.innerHTML=`<aside class="sidebar"><a class="brand" href="#${role==='siswa'?'beranda':'dashboard'}"><span class="brand-mark">${icon('school')}</span>Find My <b>PKL</b></a><div class="school">${icon('building')}<div><strong>SMK Taruna Bangsa</strong><small>Tahun ajaran 2026 / 2027</small></div></div><div class="nav-label">MENU ${role.toUpperCase()}</div><nav>${menu.map(([url,i,t])=>`<a href="#${url}" class="${r===url?'active':''}" ${r===url?'aria-current="page"':''}>${icon(i)}${t}${url==='pengajuan'?`<span class="nav-count">${mine().length}</span>`:url==='verifikasi'?`<span class="nav-count">${db.students.filter(s=>s.status==='pending').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-box">${icon('info')} <strong style="font-size:13px">Butuh arahan?</strong><p>Kenali setiap langkah perjalanan PKL kamu.</p><button data-action="guide">Panduan PKL ${icon('arrow')}</button></div><div class="profile"><span class="avatar">${role==='siswa'?esc(student().name.split(' ').map(x=>x[0]).slice(0,2).join('')):'HB'}</span><div><strong>${role==='siswa'?esc(student().name.split(' ').slice(0,2).join(' ')):'Admin HUBIN'}</strong><small>${role==='siswa'?esc(student().kelas):'Hubungan Industri'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="row"><button class="mobile-menu" aria-label="Buka navigasi" data-action="menu">${icon('menu')}</button><span>Ruang ${role==='siswa'?'siswa':'HUBIN'} <span style="color:#b4bdc2;margin:0 10px">/</span> <strong>${title}</strong></span></div><div class="topbar-right"><span class="demo">Mode prototipe</span><select aria-label="Ganti peran demo" class="role" id="role"><option value="siswa" ${role==='siswa'?'selected':''}>Demo: Siswa</option><option value="hubin" ${role==='hubin'?'selected':''}>Demo: HUBIN</option></select><button class="bell" aria-label="Notifikasi" data-action="notifications">${icon('bell')}</button><span class="avatar">${role==='siswa'?'FP':'HB'}</span></div></header><main class="content">${content(r)}<footer class="footer"><span>© 2026 Find My PKL</span><span>Data simulasi · Tersimpan di browser ini</span></footer></main></div>`}
function heading(title,sub,action=''){return `<div class="heading row"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}function stat(n,l,i){return `<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><small>${l}</small></div></div>`}function empty(t,p){return `<div class="empty">${icon('briefcase')}<h3>${t}</h3><p>${p}</p></div>`}
function content(r){if(r==='daftar')return registration();if(role==='siswa'){if(r.startsWith('detail/'))return details(Number(r.split('/')[1]));if(r==='beranda')return home();if(r==='cari'||r==='tersimpan')return listing(r);if(r==='pengajuan')return heading('Pengajuan saya','Pantau setiap langkah menuju tempat PKL pilihanmu.')+applicationTable(mine(),false);if(r==='aktif')return activeStudent();}else{if(r==='dashboard')return dashboard();if(r==='verifikasi')return verification();if(r==='review')return heading('Pengajuan siswa','Tinjau pengajuan dan catat hasil seleksi dari perusahaan.')+applicationTable(db.apps,true);if(r==='monitoring')return monitoring();if(r==='lowongan')return manageJobs();if(r==='mitra')return partners();if(r==='riwayat')return history();}return empty('Halaman tidak tersedia','Pilih menu sesuai peran kamu di navigasi.');}
function home(){const m=mine();return heading(`Halo, ${esc(student().name.split(' ')[0])} <span style="font-size:25px">✦</span>`,'Langkah kecil hari ini, awal karier hebat di masa depan.',`<span class="date">${icon('clock')} Rabu, 9 September 2026</span>`)+(student().status!=='verified'?`<div class="notice">${student().status==='rejected'?'Akun belum disetujui. Hubungi HUBIN untuk memperbaiki data.':'Akun kamu sedang menunggu verifikasi HUBIN. Kamu tetap bisa menjelajahi lowongan.'}</div>`:'')+`<section class="hero"><div><div class="eyebrow" style="margin-bottom:9px">MASA DEPAN DIMULAI DI SINI</div><h2>Temukan tempat PKL.<br>Kembangkan potensimu.</h2><p>Jelajahi kesempatan dari mitra sekolah dan temukan pengalaman yang sesuai dengan minatmu.</p><button class="primary" data-action="explore">Jelajahi lowongan ${icon('arrow')}</button></div><div class="journey"><div class="journey-item"><span>${icon('search')}</span>Temukan</div><div class="journey-line"></div><div class="journey-item"><span>${icon('file')}</span>Ajukan</div><div class="journey-line"></div><div class="journey-item"><span>${icon('briefcase')}</span>Mulai PKL</div></div></section><div class="stats">${stat(db.jobs.length,'Lowongan tersedia','briefcase')}${stat(m.length,'Total pengajuan','file')}${stat(m.filter(a=>a.status==='approved'||a.status==='pending').length,'Dalam proses','clock')}${stat(m.filter(a=>['accepted','active','completed'].includes(a.status)).length,'Pengajuan diterima','check')}</div><div class="main-grid"><section><div class="row section-head"><div><h2>Peluang untuk masa depanmu</h2><p>Temukan tempat belajar langsung dari dunia industri.</p></div><button class="text-btn" data-action="explore">Lihat semua ${icon('arrow')}</button></div>${searchTools(false)}<div id="results">${jobResults(true)}</div></section><aside class="side-panels"><div class="panel"><div class="row panel-head"><h3>Pengajuan terbaru</h3>${icon('file')}</div>${m.slice(0,3).map(a=>`<div class="application-mini"><a href="#pengajuan"><strong>${esc(job(a.job)?.title||'Lowongan diarsipkan')}</strong></a><p>${esc(co(job(a.job)?.company).name)}</p>${badge(a.status)}</div>`).join('')||'<p>Belum ada pengajuan. Mulai cari tempat PKL pilihanmu.</p>'}<button class="text-btn" style="font-size:12px;margin-top:19px" data-action="applications">Lihat semua pengajuan ${icon('arrow')}</button></div><div class="panel tips"><div class="row"><h3>Siapkan langkah terbaikmu</h3>${icon('info')}</div><ul><li>Lengkapi profil dan pastikan akunmu terverifikasi.</li><li>Pilih posisi yang sesuai dengan kompetensi dan minat.</li><li>Siapkan portofolio terbaik untuk dilihat perusahaan.</li></ul><button class="text-btn" style="font-size:12px;color:#99803f" data-action="guide">Baca panduan PKL ${icon('arrow')}</button></div></aside></div>`}
function searchTools(full){return `<div class="search-tools"><div class="search-wrap">${icon('search')}<input id="search" aria-label="Cari posisi atau perusahaan" placeholder="Cari posisi atau nama perusahaan..." value="${esc(query)}"></div><select id="city" aria-label="Filter lokasi">${['Semua','Bekasi','Jakarta','Bandung'].map(x=>`<option ${city===x?'selected':''} value="${x}">${x==='Semua'?'Semua lokasi':x}</option>`).join('')}</select>${full?`<select id="mode" aria-label="Sistem kerja">${['Semua','On-site','Hybrid','Remote'].map(x=>`<option ${mode===x?'selected':''}>${x}</option>`).join('')}</select>`:''}</div><div class="chips">${['Semua','RPL','TKJ','DKV','AKL'].map(x=>`<button data-major="${x}" class="chip ${major===x?'selected':''}">${x==='Semua'?'Semua jurusan':x}</button>`).join('')}</div>`}
function filteredJobs(saved=false){return db.jobs.filter(j=>(!saved||db.saved.includes(j.id))&&(major==='Semua'||j.major===major)&&(city==='Semua'||co(j.company).city===city)&&(mode==='Semua'||j.mode===mode)&&`${j.title} ${co(j.company).name}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='az'?a.title.localeCompare(b.title):a.id-b.id)}
function jobResults(homeView=false){const list=filteredJobs(route()==='tersimpan');const limit=homeView?4:6;const max=Math.max(1,Math.ceil(list.length/limit));page=Math.min(page,max);return (list.length?`<div class="jobs">${list.slice((page-1)*limit,page*limit).map(card).join('')}</div>`:empty('Belum ada lowongan yang cocok','Coba kata kunci atau filter lain.'))+(!homeView?`<div class="pagination"><span>${list.length} lowongan ditemukan</span><div><button data-action="prev" ${page===1?'disabled':''}>Sebelumnya</button> <span>${page} / ${max}</span> <button data-action="next" ${page===max?'disabled':''}>Berikutnya</button></div></div>`:'')}
function card(j){const c=co(j.company);return `<article class="job"><div class="company-top">${logo(j)}<button class="save ${db.saved.includes(j.id)?'saved':''}" data-save="${j.id}" aria-label="${db.saved.includes(j.id)?'Hapus dari simpanan':'Simpan lowongan'}" aria-pressed="${db.saved.includes(j.id)}">${icon('bookmark')}</button></div><h3><a href="#detail/${j.id}">${esc(j.title)}</a></h3><p class="company-name">${esc(c.name)} <span class="verified">✓</span></p><div class="meta">${icon('pin')}${esc(c.city)}, Indonesia <span>·</span> ${esc(j.mode)}</div><div class="meta">${icon('clock')}${esc(j.duration)} <span>·</span> Mulai Januari 2027</div><div class="tags"><span class="tag green">${esc(j.major)}</span>${j.skills.split(',').slice(0,2).map(t=>`<span class="tag">${esc(t.trim())}</span>`).join('')}</div><div class="job-footer"><span><b>${j.quota} kuota</b> tersedia</span><button data-detail="${j.id}">Lihat detail ${icon('arrow')}</button></div></article>`}
function listing(r){return heading(r==='tersimpan'?'PKL tersimpan':'Temukan tempat PKL-mu',r==='tersimpan'?'Pilihan yang kamu simpan untuk dipertimbangkan.':'Kesempatan belajar dari mitra industri sekolah.',`<select id="sort" aria-label="Urutkan lowongan" style="width:160px;font-size:13px"><option value="new">Rekomendasi</option><option value="az" ${sort==='az'?'selected':''}>Nama posisi A–Z</option></select>`)+searchTools(true)+`<div id="results">${jobResults()}</div>`}
function details(id){const j=job(id);if(!j)return empty('Lowongan tidak tersedia','Lowongan ini mungkin sudah dihapus. Cari kesempatan lainnya.');const c=co(j.company),applied=mine().some(a=>a.job===id);return `<button class="text-btn" data-action="explore">← Kembali ke lowongan</button><div class="detail-title">${logo(j)}<div><h1>${esc(j.title)}</h1><p>${esc(c.name)} <span class="verified">✓ Mitra sekolah</span></p></div></div><div class="detail-grid"><section class="panel detail-copy"><div class="tags"><span class="tag green">${esc(j.major)}</span><span class="tag">${esc(j.mode)}</span><span class="tag">${esc(c.city)}</span></div><h3>Tentang kesempatan ini</h3><p>${esc(j.description)}</p><h3>Yang akan kamu pelajari</h3><ul><li>Mengerjakan proyek sesuai posisi bersama tim industri.</li><li>Menerapkan kompetensi sekolah dalam pekerjaan sehari-hari.</li><li>Berkomunikasi, berkolaborasi, dan menerima umpan balik dari mentor.</li></ul><h3>Kompetensi yang dibutuhkan</h3><ul>${j.skills.split(',').map(s=>`<li>${esc(s.trim())}</li>`).join('')}</ul><h3>Proses pengajuan</h3><p>Pengajuanmu ditinjau HUBIN terlebih dahulu. Setelah disetujui, HUBIN akan mencatat hasil seleksi dari perusahaan. Persetujuan sekolah belum berarti diterima perusahaan.</p><h3>Tentang ${esc(c.name)}</h3><p>Mitra bidang ${esc(c.sector.toLowerCase())} di ${esc(c.city)}. Informasi perusahaan dan lowongan ini adalah data simulasi.</p></section><aside><div class="panel"><h3>Ringkasan lowongan</h3><p>Lokasi <strong style="float:right">${esc(c.city)}</strong></p><p>Sistem kerja <strong style="float:right">${esc(j.mode)}</strong></p><p>Durasi <strong style="float:right">${esc(j.duration)}</strong></p><p>Kuota <strong style="float:right">${j.quota} siswa</strong></p><p>Periode <strong>Januari 2027</strong></p><button class="primary" style="width:100%;margin-top:20px" data-apply="${id}" ${applied||student().status!=='verified'?'disabled':''}>${applied?'Sudah diajukan':'Ajukan PKL'}</button>${student().status!=='verified'?'<p>Akun harus diverifikasi HUBIN sebelum mengajukan.</p>':''}<button style="width:100%;margin-top:10px" data-save="${id}">${db.saved.includes(id)?'Hapus dari simpanan':'Simpan lowongan'}</button><p style="font-size:12px">Pengajuan PKL melalui sekolah tidak dipungut biaya.</p></div></aside></div>`}
function applicationTable(items,admin){const shown=items.filter(a=>statusFilter==='Semua'||a.status===statusFilter);return `<div class="chips">${['Semua','pending','approved','accepted','active','rejected','notaccepted','completed'].map(s=>`<button class="chip ${statusFilter===s?'selected':''}" data-status="${s}">${labels[s]||s}</button>`).join('')}</div>`+(shown.length?`<div class="table-wrap"><table><thead><tr>${admin?'<th>Siswa</th>':''}<th>Posisi & perusahaan</th><th>Tanggal</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${shown.map(a=>`<tr>${admin?`<td>${esc(db.students.find(s=>s.id===a.student)?.name)}<small>${esc(db.students.find(s=>s.id===a.student)?.kelas)}</small></td>`:''}<td><strong>${esc(job(a.job)?.title||a.title||'Lowongan diarsipkan')}</strong><small>${esc(co(job(a.job)?.company||a.company).name)}</small></td><td>${esc(a.date)}</td><td>${badge(a.status)}</td><td><button data-application="${a.id}">Detail</button>${admin&&a.status==='pending'?`<button class="primary" data-transition="${a.id}:approved">Setujui</button><button class="danger" data-transition="${a.id}:rejected">Tolak</button>`:''}${admin&&a.status==='approved'?`<button data-transition="${a.id}:accepted">Diterima</button><button data-transition="${a.id}:notaccepted">Tidak lolos</button>`:''}${admin&&a.status==='accepted'?`<button class="primary" data-transition="${a.id}:active">Mulai PKL</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pengajuan di tahap ini','Pengajuan yang sesuai akan muncul di sini.'))}
function registration(){return `<div class="register"><div class="eyebrow">AKUN SISWA BARU</div><h1>Mulai perjalanan PKL-mu</h1><p>Isi data sesuai identitas sekolah. HUBIN akan memeriksa akunmu sebelum kamu dapat mengajukan PKL.</p><form id="register-form" class="panel"><div class="form-grid"><label class="field wide">Nama lengkap<input name="name" required maxlength="80" placeholder="Nama sesuai data sekolah"></label><label class="field">Kelas<input name="kelas" required placeholder="Contoh: XI RPL 6"></label><label class="field">Jurusan<select name="major">${['RPL','TKJ','DKV','AKL'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field wide">Email<input type="email" name="email" required placeholder="nama@example.com"></label></div><p>Ini pendaftaran demo, tanpa autentikasi. Gunakan data contoh.</p><button class="primary" type="submit" style="width:100%;margin-top:16px">Daftar & minta verifikasi</button></form></div>`}
function dashboard(){return heading('Dashboard HUBIN','Kelola perjalanan PKL siswa dalam satu tempat.',`<button class="primary" data-action="new-job">${icon('plus')} Tambah lowongan</button>`)+`<div class="stats">${stat(db.students.length,'Siswa terdaftar','users')}${stat(db.students.filter(s=>s.status==='pending').length,'Perlu verifikasi','clock')}${stat(db.apps.filter(a=>a.status==='pending').length,'Pengajuan baru','file')}${stat(db.apps.filter(a=>a.status==='active').length,'Siswa PKL aktif','briefcase')}</div><div class="hero" style="margin-bottom:26px"><div><div class="eyebrow">TINDAK LANJUT HARI INI</div><h2>Bantu siswa mengambil langkah berikutnya.</h2><p>${db.students.filter(s=>s.status==='pending').length} akun menunggu verifikasi dan ${db.apps.filter(a=>a.status==='pending').length} pengajuan perlu ditinjau.</p><button class="primary" data-action="verify-page">Verifikasi akun ${icon('arrow')}</button></div></div><h2 style="margin-bottom:18px">Pengajuan siswa</h2>`+applicationTable(db.apps,true)}
function verification(){return heading('Verifikasi akun siswa','Pastikan identitas dan jurusan siswa sesuai data sekolah.',`<button data-action="register">${icon('plus')} Coba pendaftaran</button>`)+`<div class="table-wrap"><table><thead><tr><th>Nama siswa</th><th>Kelas</th><th>Jurusan</th><th>Status akun</th><th>Tindakan</th></tr></thead><tbody>${db.students.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.email)}</small></td><td>${esc(s.kelas)}</td><td>${esc(s.major)}</td><td><span class="badge ${s.status==='verified'?'good':s.status==='rejected'?'bad':''}">${s.status==='verified'?'Terverifikasi':s.status==='rejected'?'Ditolak':'Menunggu verifikasi'}</span></td><td>${s.status==='pending'?`<button class="primary" data-verify="${s.id}:verified">Verifikasi</button><button class="danger" data-verify="${s.id}:rejected">Tolak</button>`:s.status==='rejected'?`<button data-verify="${s.id}:verified">Verifikasi ulang</button>`:'Selesai'}</td></tr>`).join('')}</tbody></table></div>`}
function activeStudent(){const active=mine().filter(a=>['active','accepted','completed'].includes(a.status));return heading('Perjalanan PKL saya','Informasi penempatan dan catatan pembimbing sekolah.')+(active.length?active.map(a=>`<div class="panel"><div class="row"><h2>${esc(job(a.job)?.title)}</h2>${badge(a.status)}</div><p>${esc(co(job(a.job)?.company).name)}</p><div class="steps">${['Disetujui HUBIN','Diterima perusahaan','PKL berlangsung','PKL selesai'].map((s,i)=>`<span class="step ${i<({accepted:2,active:3,completed:4}[a.status])?'done':''}">${i+1}. ${s}</span>`).join('')}</div><p>${a.status==='accepted'?'HUBIN akan mengonfirmasi tanggal mulai dan pembimbing PKL.':`Pembimbing sekolah: ${esc(a.mentor||'Belum ditentukan')} · Mulai: ${esc(a.start||'Belum ditentukan')}`}</p><h3>Catatan monitoring</h3><p>${esc(a.monitor||'Belum ada catatan dari HUBIN.')}</p></div>`).join(''):empty('Belum ada penempatan PKL','Penempatan muncul setelah kamu dinyatakan diterima perusahaan.'))}
function monitoring(){const list=db.apps.filter(a=>a.status==='active'||a.status==='accepted');return heading('Monitoring PKL','Pantau penempatan, pembimbing, dan perkembangan siswa.')+(list.length?`<div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Perusahaan</th><th>Status</th><th>Pembimbing</th><th>Tindakan</th></tr></thead><tbody>${list.map(a=>`<tr><td>${esc(db.students.find(s=>s.id===a.student)?.name)}</td><td>${esc(co(job(a.job)?.company).name)}</td><td>${badge(a.status)}</td><td>${esc(a.mentor||'Belum ditentukan')}</td><td>${a.status==='accepted'?`<button data-transition="${a.id}:active" class="primary">Mulai PKL</button>`:`<button data-monitor="${a.id}">Catat perkembangan</button><button data-transition="${a.id}:completed">Selesaikan PKL</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada siswa PKL aktif','Catat hasil seleksi perusahaan pada menu Pengajuan siswa terlebih dahulu.'))}
function manageJobs(){return heading('Kelola lowongan PKL','Perbarui kesempatan belajar dari mitra sekolah.',`<button class="primary" data-action="new-job">${icon('plus')} Tambah lowongan</button>`)+`<div class="table-wrap"><table><thead><tr><th>Posisi</th><th>Perusahaan</th><th>Jurusan</th><th>Kuota</th><th>Tindakan</th></tr></thead><tbody>${db.jobs.map(j=>`<tr><td><strong>${esc(j.title)}</strong><small>${esc(j.mode)} · ${esc(j.duration)}</small></td><td>${esc(co(j.company).name)}</td><td>${esc(j.major)}</td><td>${j.quota}</td><td><button data-editjob="${j.id}">Edit</button><button class="danger" data-deletejob="${j.id}">Hapus</button></td></tr>`).join('')}</tbody></table></div>`}
function partners(){return heading('Mitra perusahaan','Jejaring industri untuk tumbuh bersama siswa.',`<button class="primary" data-action="new-company">${icon('plus')} Tambah mitra</button>`)+`<div class="jobs">${db.companies.map(c=>`<div class="panel"><div class="row"><h3>${esc(c.name)}</h3>${icon('building')}</div><p>${esc(c.sector)} · ${esc(c.city)}</p><p>${esc(c.contact)}</p><div class="tags"><span class="tag">${db.jobs.filter(j=>j.company===c.id).length} lowongan</span><span class="tag green">${db.history.filter(h=>h.company===c.id).length} alumni PKL</span></div><button data-company-history="${c.id}">Lihat riwayat siswa</button> <button data-editcompany="${c.id}">Edit</button> <button class="danger" data-deletecompany="${c.id}">Hapus</button></div>`).join('')}</div>`}
let historyCompany='Semua';function history(){const hs=db.history.filter(h=>historyCompany==='Semua'||h.company===Number(historyCompany));return heading('Riwayat penempatan PKL','Telusuri siswa yang telah menyelesaikan PKL di perusahaan mitra.')+`<label class="field" style="max-width:320px">Perusahaan<select id="history-company"><option>Semua</option>${db.companies.map(c=>`<option value="${c.id}" ${String(c.id)===String(historyCompany)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`+(hs.length?`<div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Perusahaan & posisi</th><th>Periode</th><th>Catatan akhir</th></tr></thead><tbody>${hs.map(h=>`<tr><td>${esc(h.studentName)}<small>${esc(h.kelas)}</small></td><td>${esc(co(h.company).name)}<small>${esc(h.title)}</small></td><td>${esc(h.period)}</td><td style="white-space:normal;min-width:220px">${esc(h.note)}<small>${badge('completed')}</small></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada riwayat di perusahaan ini','Penempatan yang diselesaikan HUBIN akan tersimpan otomatis.'))}
function openModal(title,body,formId=''){modal.innerHTML=`<div class="row"><h2>${title}</h2><button data-action="close" aria-label="Tutup dialog">×</button></div>${formId?`<form id="${formId}">${body}</form>`:body}`;modal.showModal()}
function actions(text='Simpan'){return `<div class="actions"><button type="button" data-action="close">Batal</button><button class="primary" type="submit">${text}</button></div>`}
function jobForm(id){const j=job(id)||{title:'',company:db.companies[0]?.id,major:'RPL',mode:'Hybrid',duration:'6 bulan',quota:2,skills:'',description:''};if(!db.companies.length){toast('Tambahkan mitra perusahaan terlebih dahulu.');return}openModal(id?'Edit lowongan':'Tambah lowongan',`<input type="hidden" name="id" value="${id||''}"><label class="field">Nama posisi<input name="title" required value="${esc(j.title)}"></label><label class="field">Perusahaan<select name="company">${db.companies.map(c=>`<option value="${c.id}" ${j.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Jurusan<select name="major">${['RPL','TKJ','DKV','AKL'].map(x=>`<option ${j.major===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Sistem kerja<select name="mode">${['On-site','Hybrid','Remote'].map(x=>`<option ${j.mode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Kuota<input type="number" name="quota" min="1" max="100" required value="${j.quota}"></label><label class="field">Durasi<select name="duration">${['3 bulan','6 bulan','12 bulan'].map(x=>`<option ${j.duration===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">Kompetensi (pisahkan dengan koma)<input name="skills" required value="${esc(j.skills)}"></label><label class="field">Deskripsi<textarea name="description" required>${esc(j.description)}</textarea></label>${actions()}`,'job-form')}
function companyForm(id){const c=co(id);openModal(id?'Edit mitra':'Tambah mitra',`<input name="id" type="hidden" value="${id||''}">${[['name','Nama perusahaan'],['city','Kota'],['sector','Bidang industri'],['contact','Email kontak']].map(([key,t])=>`<label class="field">${t}<input name="${key}" ${key==='contact'?'type="email"':''} required value="${id?esc(c[key]):''}"></label>`).join('')}${actions()}`,'company-form')}
function transition(id,next){const a=db.apps.find(x=>x.id===id);const valid={pending:['approved','rejected'],approved:['accepted','notaccepted'],accepted:['active'],active:['completed']};if(role!=='hubin'||!a||!valid[a.status]?.includes(next))return;openModal(({approved:'Setujui pengajuan?',rejected:'Tolak pengajuan?',accepted:'Catat hasil diterima?',notaccepted:'Catat hasil tidak lolos?',active:'Mulai penempatan PKL',completed:'Selesaikan PKL'})[next],`<input type="hidden" name="id" value="${id}"><input type="hidden" name="next" value="${next}"><p>${esc(db.students.find(s=>s.id===a.student)?.name)} · ${esc(job(a.job)?.title)}</p>${next==='active'?'<label class="field">Tanggal mulai<input type="date" name="start" required></label><label class="field">Pembimbing sekolah<input name="mentor" required placeholder="Nama guru pembimbing"></label>':''}<label class="field">${next==='completed'?'Catatan akhir & hasil PKL':next==='rejected'||next==='notaccepted'?'Alasan keputusan':'Catatan keputusan'}<textarea name="reason" required placeholder="Tuliskan catatan yang bisa dipahami siswa"></textarea></label>${next==='completed'?'<p>Penempatan akan dipindahkan ke riwayat dan tidak lagi muncul sebagai PKL aktif.</p>':''}${actions('Konfirmasi')}`,'transition-form')}
function confirmation(title,text,fn){openModal(title,`<p>${esc(text)}</p><div class="actions"><button data-action="close">Batal</button><button class="primary" id="confirm">Konfirmasi</button></div>`);document.querySelector('#confirm').onclick=()=>{fn();modal.close();persist();render()}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(d.action==='public-menu'){const n=document.querySelector('.public-links');const open=n.classList.toggle('open');b.setAttribute('aria-expanded',String(open));return}if(d.scroll){document.querySelector('.public-links')?.classList.remove('open');document.querySelector('#'+d.scroll)?.scrollIntoView({behavior:'smooth'});return}if(d.publicCategory){const map={'Software Development':['Developer','RPL'],'IT Support':['IT Support','TKJ'],'UI/UX':['UI/UX','DKV'],'Networking':['','TKJ'],'Multimedia':['','DKV'],'Akuntansi':['','AKL'],'Administrasi':['Administrasi','AKL'],'Otomotif':['Otomotif','Semua']};[query,major]=map[d.publicCategory]||['','Semua'];city='Semua';mode='Semua';role='siswa';nav('cari');return}if(d.action==='login'){role='siswa'}if(d.action==='menu'){document.querySelector('.sidebar').classList.toggle('open');return}if(b.tagName==='A')document.querySelector('.sidebar')?.classList.remove('open');if(d.action==='close'){modal.close();return}if(d.action==='explore'){query='';major='Semua';city='Semua';mode='Semua';role='siswa';nav('cari')}if(d.action==='applications')nav('pengajuan');if(d.action==='verify-page')nav('verifikasi');if(d.action==='register'){modal.close();role='siswa';nav('daftar');render()}if(d.action==='new-job'&&role==='hubin')jobForm();if(d.action==='new-company'&&role==='hubin')companyForm();if(d.action==='prev'||d.action==='next'){page+=d.action==='prev'?-1:1;updateResults()}if(d.major){major=d.major;page=1;render()}if(d.status){statusFilter=d.status;render()}if(d.detail){role='siswa';nav('detail/'+d.detail);}if(d.save){const id=Number(d.save);db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id];persist();render();toast(db.saved.includes(id)?'Lowongan disimpan.':'Lowongan dihapus dari simpanan.')}if(d.apply){if(student().status!=='verified'||mine().some(a=>a.job===Number(d.apply)))return;openModal('Ajukan PKL',`<input type="hidden" name="job" value="${d.apply}"><p>${esc(job(Number(d.apply)).title)} · ${esc(co(job(Number(d.apply)).company).name)}</p><label class="field">Ceritakan minat dan kesiapanmu<textarea name="note" required minlength="20" placeholder="Minimal 20 karakter. Jelaskan mengapa kamu ingin belajar di posisi ini."></textarea></label><p>Pengajuan akan dikirim ke HUBIN untuk ditinjau.</p>${actions('Kirim pengajuan')}`,'apply-form')}if(d.application){const a=db.apps.find(x=>x.id===Number(d.application));openModal('Detail pengajuan',`<h3>${esc(job(a.job)?.title)}</h3><p>${esc(co(job(a.job)?.company).name)} · ${esc(a.date)}</p>${badge(a.status)}<h3 style="margin-top:22px">Motivasi siswa</h3><p>${esc(a.note||'Tidak ada catatan.')}</p><h3 style="margin-top:22px">Catatan HUBIN</h3><p>${esc(a.reason||'Pengajuan sedang diproses.')}</p><div class="steps">${['Pengajuan','Review HUBIN','Seleksi perusahaan','Penempatan'].map((x,i)=>`<span class="step ${i<=({pending:0,rejected:1,approved:1,accepted:2,notaccepted:2,active:3,completed:3}[a.status])?'done':''}">${i+1}. ${x}</span>`).join('')}</div>`)}if(d.transition){const [id,next]=d.transition.split(':');transition(Number(id),next)}if(d.verify&&role==='hubin'){const [id,next]=d.verify.split(':');confirmation(next==='verified'?'Verifikasi akun siswa?':'Tolak verifikasi akun?',next==='verified'?'Pastikan nama dan kelas sesuai data sekolah. Siswa akan dapat mengajukan PKL.':'Akun tidak dapat mengajukan PKL sampai diverifikasi ulang.',()=>{db.students.find(s=>s.id===Number(id)).status=next;toast('Status akun diperbarui.')})}if(d.editjob&&role==='hubin')jobForm(Number(d.editjob));if(d.deletejob&&role==='hubin'){const id=Number(d.deletejob);if(db.apps.some(a=>a.job===id)){toast('Lowongan memiliki pengajuan. Pertahankan lowongan agar riwayat siswa tetap utuh.');return}confirmation('Hapus lowongan?','Lowongan akan dihapus dari daftar dan simpanan siswa.',()=>{db.jobs=db.jobs.filter(j=>j.id!==id);db.saved=db.saved.filter(j=>j!==id);toast('Lowongan dihapus.')})}if(d.editcompany&&role==='hubin')companyForm(Number(d.editcompany));if(d.deletecompany&&role==='hubin'){const id=Number(d.deletecompany);if(db.jobs.some(j=>j.company===id)||db.history.some(h=>h.company===id)){toast('Mitra masih memiliki lowongan atau riwayat PKL sehingga tidak dapat dihapus.');return}confirmation('Hapus mitra?','Mitra ini akan dihapus dari daftar perusahaan.',()=>db.companies=db.companies.filter(c=>c.id!==id))}if(d.companyHistory){historyCompany=d.companyHistory;nav('riwayat')}if(d.monitor&&role==='hubin'){const a=db.apps.find(x=>x.id===Number(d.monitor));openModal('Catat perkembangan PKL',`<input type="hidden" name="id" value="${a.id}"><label class="field">Pembimbing<input name="mentor" required value="${esc(a.mentor)}"></label><label class="field">Catatan monitoring<textarea name="monitor" required>${esc(a.monitor||'')}</textarea></label>${actions()}`,'monitor-form')}if(d.action==='guide')openModal('Panduan perjalanan PKL',`<ol class="detail-copy"><li>Daftar akun dengan nama, kelas, dan jurusan.</li><li>Tunggu HUBIN memverifikasi data sekolahmu.</li><li>Cari lowongan, baca detail, lalu ajukan PKL.</li><li>HUBIN meninjau pengajuan sebelum seleksi perusahaan.</li><li>Pantau hasil seleksi di Pengajuan saya.</li><li>Setelah diterima, HUBIN memulai dan memonitor PKL.</li><li>PKL selesai tersimpan dalam riwayat sekolah.</li></ol><button class="primary" data-action="register">Coba daftar siswa baru</button>`);if(d.action==='notifications')openModal('Notifikasi',role==='siswa'?`<p>Status akun: ${student().status==='verified'?'Terverifikasi':student().status==='pending'?'Menunggu verifikasi':'Ditolak'}</p>${mine().map(a=>`<div class="application-mini"><strong>${esc(job(a.job)?.title)}</strong>${badge(a.status)}</div>`).join('')}`:`<p>${db.students.filter(s=>s.status==='pending').length} akun menunggu verifikasi.</p><p>${db.apps.filter(a=>a.status==='pending').length} pengajuan menunggu keputusan HUBIN.</p>`)});
function updateResults(){const r=document.querySelector('#results');if(r)r.innerHTML=jobResults(route()==='beranda')}
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=1;clearTimeout(searchTimer);const results=document.querySelector('#results');results.innerHTML='<div class="jobs" aria-label="Memuat hasil"><div class="skeleton"></div><div class="skeleton"></div></div>';searchTimer=setTimeout(updateResults,180)}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='role'){role=t.value;statusFilter='Semua';nav(role==='siswa'?'beranda':'dashboard');render()}if(t.id==='city'){city=t.value;page=1;updateResults()}if(t.id==='mode'){mode=t.value;page=1;updateResults()}if(t.id==='sort'){sort=t.value;updateResults()}if(t.id==='history-company'){historyCompany=t.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const v=Object.fromEntries(new FormData(f));if(f.id==='public-search'){query=(v.q||'').trim();major='Semua';city='Semua';mode='Semua';role='siswa';nav('cari');return}if([...f.querySelectorAll('[required]')].some(x=>!x.value.trim())){toast('Lengkapi semua kolom wajib.');return}if(f.id==='register-form'){if(db.students.some(s=>s.email.toLowerCase()===v.email.toLowerCase())){toast('Email sudah terdaftar. Gunakan email demo lain.');return}const id=uid();db.students.push({...v,id,status:'pending'});db.current=id;persist();nav('beranda');toast('Pendaftaran berhasil. Menunggu verifikasi HUBIN.');return}if(f.id==='apply-form'){if(role!=='siswa'||student().status!=='verified'||mine().some(a=>a.job===Number(v.job)))return;db.apps.unshift({id:uid(),student:student().id,job:Number(v.job),status:'pending',note:v.note,date:new Date().toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})});toast('Pengajuan berhasil dikirim ke HUBIN.')}if(f.id==='job-form'&&role==='hubin'){const data={...v,id:Number(v.id)||uid(),company:Number(v.company),quota:Number(v.quota)};if(v.id)db.jobs=db.jobs.map(j=>j.id===data.id?data:j);else db.jobs.push(data);toast('Lowongan berhasil disimpan.')}if(f.id==='company-form'&&role==='hubin'){const data={...v,id:Number(v.id)||uid()};if(v.id)db.companies=db.companies.map(c=>c.id===data.id?data:c);else db.companies.push(data);toast('Mitra berhasil disimpan.')}if(f.id==='transition-form'&&role==='hubin'){const a=db.apps.find(a=>a.id===Number(v.id));if(v.next==='active'&&db.apps.some(b=>b.student===a.student&&b.status==='active')){toast('Siswa sudah memiliki PKL aktif. Selesaikan penempatan sebelumnya.');return}a.status=v.next;a.reason=v.reason;if(v.next==='active'){a.start=v.start;a.mentor=v.mentor}if(v.next==='completed'){const s=db.students.find(s=>s.id===a.student),j=job(a.job);db.history.unshift({id:uid(),studentName:s.name,kelas:s.kelas,company:j.company,title:j.title,period:`${a.start} – ${new Date().toLocaleDateString('id-ID')}`,note:v.reason})}toast('Status pengajuan diperbarui.')}if(f.id==='monitor-form'&&role==='hubin'){const a=db.apps.find(a=>a.id===Number(v.id));a.mentor=v.mentor;a.monitor=v.monitor;toast('Catatan monitoring disimpan.')}persist();modal.close();render()});
function publicHome(){
 const categories=['Software Development','IT Support','UI/UX','Networking','Multimedia','Akuntansi','Administrasi','Otomotif'];
 const steps=[['users','Daftar sebagai siswa','Buat akun dengan data sekolah yang benar.'],['check','Akun diverifikasi HUBIN','HUBIN memeriksa identitas dan jurusanmu.'],['search','Cari tempat PKL','Gunakan pencarian dan filter yang mudah.'],['file','Ajukan PKL','Kirim minatmu ke lowongan pilihan.'],['school','HUBIN memberi persetujuan','Sekolah meninjau kesesuaian pengajuan.'],['clock','Ikuti proses seleksi','Pantau hasil seleksi dari perusahaan.'],['briefcase','Mulai PKL','Mulai penempatan dengan pendampingan sekolah.']];
 return `<div class="public-page">
 <header class="public-nav"><div class="public-container nav-inner"><a class="brand" href="#publik" aria-label="Find My PKL, beranda"><span class="brand-mark">${icon('school')}</span>Find My <b>PKL</b></a><button class="public-menu-btn" data-action="public-menu" aria-label="Buka menu" aria-expanded="false">${icon('menu')}</button><nav class="public-links" aria-label="Navigasi utama"><a href="#publik">Beranda</a><button data-action="explore">Cari PKL</button><button data-scroll="companies">Perusahaan</button><button data-scroll="how">Panduan</button><button data-scroll="about">Tentang</button></nav><div class="public-actions"><a class="login-link" href="#beranda" data-action="login">Masuk</a><a class="primary public-register" href="#daftar">Daftar</a></div></div></header>
 <main>
 <section class="public-hero"><div class="public-container hero-inner"><div class="hero-copy"><span class="public-kicker">PORTAL PKL SISWA SMK</span><h1>Temukan Tempat PKL yang Tepat Untukmu</h1><p>Cari peluang PKL dari perusahaan yang telah terdaftar dan pantau proses pengajuanmu dalam satu platform.</p><form id="public-search" class="hero-search"><span>${icon('search')}</span><input name="q" aria-label="Cari peluang PKL" placeholder="Cari posisi, perusahaan, bidang, atau lokasi..."><button class="primary" type="submit">Cari PKL</button></form><div class="hero-cta"><a class="primary" href="#daftar">Daftar Sekarang ${icon('arrow')}</a><small>Gratis untuk siswa SMK</small></div></div><div class="hero-board" aria-label="Ringkasan kesempatan PKL"><div class="board-top"><span class="status-dot"></span><span>Kesempatan terbaru</span><b>${db.jobs.length} aktif</b></div>${db.jobs.slice(0,3).map(j=>`<button class="board-job" data-detail="${j.id}">${logo(j)}<span><strong>${esc(j.title)}</strong><small>${esc(co(j.company).name)} · ${esc(co(j.company).city)}</small></span><i>${icon('arrow')}</i></button>`).join('')}<div class="board-note">${icon('check')} Mitra terdaftar dan dikelola sekolah</div></div></div></section>
 <section class="category-strip"><div class="public-container"><div class="category-label">Jelajahi berdasarkan bidang</div><div class="public-chips">${categories.map(c=>`<button data-public-category="${c}">${esc(c)}</button>`).join('')}</div></div></section>
 <section class="public-section" id="recommendations"><div class="public-container"><div class="public-section-head"><div><span class="public-kicker">PILIHAN TERBARU</span><h2>Rekomendasi PKL Untukmu</h2><p>Peluang dari mitra sekolah untuk berbagai jurusan dan minat.</p></div><button class="text-btn" data-action="explore">Lihat semua lowongan ${icon('arrow')}</button></div><div class="public-job-grid">${db.jobs.slice(0,6).map(publicJobCard).join('')}</div></div></section>
 <section class="partner-band" id="companies"><div class="public-container"><div class="public-section-head compact"><div><span class="public-kicker">MITRA SEKOLAH</span><h2>Belajar langsung bersama perusahaan</h2></div><p>Lowongan dikelola HUBIN agar proses pengajuan siswa tetap jelas dan terpantau.</p></div><div class="partner-list">${db.companies.slice(0,6).map((c,i)=>`<div class="partner-item"><span class="company-logo logo-${(i+1)%5}">${esc(c.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.sector)} · ${esc(c.city)}</small></div></div>`).join('')}</div></div></section>
 <section class="public-section how-section" id="how"><div class="public-container"><div class="public-section-head centered"><div><span class="public-kicker">LANGKAH YANG JELAS</span><h2>Bagaimana Find My PKL Bekerja?</h2><p>Dari pendaftaran sampai hari pertama PKL, setiap proses dapat dipantau.</p></div></div><div class="how-grid">${steps.map((s,i)=>`<article class="how-card"><span class="how-number">${String(i+1).padStart(2,'0')}</span><div class="how-icon">${icon(s[0])}</div><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div></div></section>
 <section class="public-stats"><div class="public-container stats-inner"><div><strong>24+</strong><span>Lowongan PKL Aktif</span></div><div><strong>12</strong><span>Perusahaan Mitra</span></div><div><strong>386</strong><span>Siswa Terdaftar</span></div><div><strong>271</strong><span>Siswa Berhasil Mendapat PKL</span></div></div></section>
 <section class="about-band" id="about"><div class="public-container about-inner"><div><span class="public-kicker">TENTANG PLATFORM</span><h2>Satu tempat untuk perjalanan PKL yang lebih tertata.</h2></div><p>Find My PKL membantu siswa menemukan peluang, sekolah mengelola persetujuan, dan seluruh proses penempatan tercatat dengan rapi.</p><a class="primary" href="#daftar">Mulai sebagai siswa ${icon('arrow')}</a></div></section>
 </main><footer class="public-footer"><div class="public-container footer-grid"><div><a class="brand footer-brand" href="#publik"><span class="brand-mark">${icon('school')}</span>Find My <b>PKL</b></a><p>Platform penemuan dan pengelolaan PKL untuk siswa SMK.</p></div><div><strong>Jelajahi</strong><button data-action="explore">Cari PKL</button><button data-scroll="companies">Perusahaan</button><button data-scroll="how">Panduan</button></div><div><strong>Akun</strong><a href="#beranda" data-action="login">Masuk</a><a href="#daftar">Daftar siswa</a></div><div><strong>Sekolah</strong><p>SMK Taruna Bangsa<br>Bekasi, Indonesia</p></div></div><div class="public-container footer-bottom"><span>© 2026 Find My PKL</span><span>Prototipe data simulasi</span></div></footer></div>`
}
function publicJobCard(j){const c=co(j.company),deadlines=['30 Sep 2026','5 Okt 2026','12 Okt 2026','18 Okt 2026'];return `<article class="public-job-card"><div class="public-job-top">${logo(j)}<span class="badge good">Dibuka</span></div><p class="public-company">${esc(c.name)} <span class="verified">✓</span></p><h3>${esc(j.title)}</h3><div class="public-job-meta"><span>${icon('pin')}${esc(c.city)}</span><span>${icon('briefcase')}${esc(j.mode)}</span></div><div class="tags"><span class="tag green">${esc(j.major)}</span><span class="tag">${esc(j.skills.split(',')[0].trim())}</span></div><dl><div><dt>Kuota tersedia</dt><dd>${j.quota} siswa</dd></div><div><dt>Batas daftar</dt><dd>${deadlines[(j.id-1)%deadlines.length]}</dd></div></dl><button data-detail="${j.id}">Lihat Detail ${icon('arrow')}</button></article>`}

window.addEventListener('hashchange',()=>{page=1;statusFilter='Semua';render();window.scrollTo(0,0)});render();if(storageFailed)toast('Data lokal tidak dapat dibaca. Sesi demo baru telah dimulai.');
